import java.util.*;
​
class Node {
    int value; // 节点的值
    int num;   // 子树拥有的节点数量
    Node left, right;
​
    Node(int value, int num) {
        this.value = value;
        this.num = num;
        this.left = null;
        this.right = null;
    }
}
​
// 自定义排序（按照节点值升序，若值相同则按照子树大小升序）
class CompareItem implements Comparator<Node> {
    public int compare(Node a, Node b) {
        if (a.value == b.value) {
            return Integer.compare(a.num, b.num);
        }
        return Integer.compare(a.value, b.value);
    }
}
​
public class Main {
    // 中序遍历（递归）
    static void dfs(Node root) {
        if (root == null) return;
        dfs(root.left);
        System.out.print(root.value + " ");
        dfs(root.right);
    }
​
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        PriorityQueue<Node> pq = new PriorityQueue<>(new CompareItem());
​
        for (int i = 0; i < n; i++) {
            int tmp = scanner.nextInt();
            pq.offer(new Node(tmp, 1));
        }
        scanner.close();
​
        Node root = null;
        while (pq.size() > 1) {
            Node left = pq.poll();
            Node right = pq.poll();
            Node parent = new Node(left.value + right.value, left.num + right.num + 1);
            parent.left = left;
            parent.right = right;
            pq.offer(parent);
        }
        root = pq.poll();
​
        dfs(root);
    }
}
