// 自定义排序规则（优先队列）
class PriorityQueue {
    constructor() {
        this.data = [];
    }
​
    push(node) {
        this.data.push(node);
        this.data.sort((a, b) => {
            if (a.value === b.value) {
                return a.num - b.num; // 如果值相等，按子树大小排序
            }
            return a.value - b.value; // 按值从小到大排序
        });
    }
​
    pop() {
        return this.data.shift();
    }
​
    size() {
        return this.data.length;
    }
​
    top() {
        return this.data[0];
    }
}
