package main
​
import (
    "bufio"
    "container/heap"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
// Node 结构体
type Node struct {
    value int
    num   int
    left  *Node
    right *Node
}
​
// PriorityQueue 实现最小堆
type PriorityQueue []*Node
​
func (pq PriorityQueue) Len() int { return len(pq) }
​
func (pq PriorityQueue) Less(i, j int) bool {
    if pq[i].value == pq[j].value {
        return pq[i].num < pq[j].num // 若值相等，按子树大小排序
    }
    return pq[i].value < pq[j].value // 按值从小到大排序
}
​
func (pq PriorityQueue) Swap(i, j int) {
    pq[i], pq[j] = pq[j], pq[i]
}
​
func (pq *PriorityQueue) Push(x interface{}) {
    *pq = append(*pq, x.(*Node))
}
​
func (pq *PriorityQueue) Pop() interface{} {
    old := *pq
    n := len(old)
    item := old[n-1]
    *pq = old[0 : n-1]
    return item
}
​
// 中序遍历
func dfs(root *Node) {
    if root == nil {
        return
    }
    dfs(root.left)
    fmt.Print(root.value, " ")
    dfs(root.right)
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
​
    // 读取 n
    line, _ := reader.ReadString('\n')
    n, _ := strconv.Atoi(strings.TrimSpace(line))
​
    // 读取数组
    line, _ = reader.ReadString('\n')
    strs := strings.Fields(line)
​
    if len(strs) != n {
        fmt.Println("输入数据不匹配")
        return
    }
​
    pq := &PriorityQueue{}
    heap.Init(pq)
​
    // 读取输入数据并加入优先队列
    for _, s := range strs {
        value, _ := strconv.Atoi(s)
        heap.Push(pq, &Node{value: value, num: 1})
    }
​
    // 构建哈夫曼树
    var root *Node
    for pq.Len() > 1 {
        left := heap.Pop(pq).(*Node)
        right := heap.Pop(pq).(*Node)
        parent := &Node{value: left.value + right.value, num: left.num + right.num + 1, left: left, right: right}
        heap.Push(pq, parent)
    }
    root = heap.Pop(pq).(*Node)
​
    // 中序遍历输出
    dfs(root)
    fmt.Println()
}
